// Config › Gerais › abas da "Alterando Bandeira" da Machine (Motorista, Passageiro, Financeiro, Filtros, Formas de pagamento e
// Recursos Premium): cada linha é um campo (ou grupo de campos) com rótulo, opções, valor padrão e o texto de ajuda da Machine.
// O painel desenha o formulário a partir daqui e o servidor valida e grava pelos mesmos dados (um lugar só). A aba Despacho tem
// o seu próprio arquivo (config/bandeira.ts).

export interface OpcaoForm { v: string; t: string; desab?: boolean }
export type TipoControle = "numero" | "texto" | "area" | "selecao" | "radio" | "caixa";
export interface ControleForm {
  /** Chave do valor guardado (igual ao nome do campo na Machine, sem o prefixo). */
  nome: string; tipo: TipoControle;
  /** Texto ao lado do campo (rádio e caixa usam as opções/o próprio texto). */
  rotulo?: string;
  opcoes?: OpcaoForm[];
  /** "categorias": as opções vêm das categorias da central. */
  fonte?: "categorias";
  padrao: string | number | boolean | null;
  min?: number; max?: number; passo?: number; tamanho?: number; dica?: string; unidade?: string;
  /** Só fica habilitado quando o controle "nome" tem um destes valores. */
  de?: { nome: string; em: string[] };
}
export interface LinhaForm { rotulo: string; controles: ControleForm[]; ajuda: string; especial?: "documentos" | "previa" | "mensagens" }
export type ItemForm = { secao: string } | LinhaForm;
export interface AbaForm { id: string; titulo: string; intro: string[]; itens: ItemForm[] }
export type ValorForm = string | number | boolean;
export type ValoresForm = Record<string, ValorForm>;

export const ehLinha = (i: ItemForm): i is LinhaForm => "controles" in i;
export function controlesDe(abas: AbaForm[]): ControleForm[] {
  return abas.flatMap((a) => a.itens.filter(ehLinha).flatMap((l) => l.controles));
}

const SN = (padrao: "1" | "0"): Pick<ControleForm, "opcoes" | "padrao"> => ({ opcoes: [{ v: "1", t: "Sim" }, { v: "0", t: "Não" }], padrao });
const radioSN = (nome: string, padrao: "1" | "0", de?: ControleForm["de"]): ControleForm => ({ nome, tipo: "radio", ...SN(padrao), ...(de ? { de } : {}) });
const linha = (rotulo: string, controles: ControleForm[], ajuda = ""): LinhaForm => ({ rotulo, controles, ajuda });

