/** Mensagens rápidas: a Machine deixa adicionar e remover; aqui há até 20 espaços por lista e a tela mostra só os preenchidos. */
export const MAX_MENSAGENS_RAPIDAS = 20;
for (const a of GERADAS) {
  for (const i of a.itens) {
    const base = ehLinha(i) ? i.controles[0] : undefined;
    if (!ehLinha(i) || !base || !/^msg_[PC]_0$/.test(base.nome)) continue;
    i.especial = "mensagens";
    for (let n = i.controles.length; n < MAX_MENSAGENS_RAPIDAS; n++) i.controles.push({ ...base, nome: `${base.nome.slice(0, 6)}${n}`, padrao: "" });
  }
}

/** Mensagens rápidas do motorista para o cliente (lista da Machine, sem espaços vazios). Vazio = a central nunca definiu. */
export const mensagensRapidasDe = (v: ValoresForm, lista: "P" | "C"): string[] =>
  Array.from({ length: MAX_MENSAGENS_RAPIDAS }, (_, n) => String(v[`msg_${lista}_${n}`] ?? "").trim()).filter(Boolean);

const g = (id: string) => GERADAS.find((a) => a.id === id)!;
/** As abas desta tela, na ordem da Machine (a aba Despacho, que fica entre Passageiro e Financeiro, é desenhada à parte). */
export const ABAS_FORM: AbaForm[] = [g("motorista"), g("passageiro"), g("financeiro"), g("filtros"), ABA_PAGAMENTOS, ABA_PREMIUM, ABA_SAQUE];

export const TODOS_CONTROLES: ControleForm[] = controlesDe(ABAS_FORM);
const porNome = new Map(TODOS_CONTROLES.map((c) => [c.nome, c]));

/** Valor inicial de cada campo (o que vale quando a central nunca gravou). */
export function valoresPadrao(): ValoresForm {
  const v: ValoresForm = {};
  for (const c of TODOS_CONTROLES) v[c.nome] = c.tipo === "caixa" ? !!c.padrao : c.padrao === null || c.padrao === undefined ? "" : (c.padrao as string | number);
  return v;
}

const dentro = (n: number, c: ControleForm) => Math.min(c.max ?? 1e9, Math.max(c.min ?? -1e9, n));
/** Lê um valor do formulário do jeito certo para o campo (texto sem marcas, número no limite, opção que existe). */
export function sanearValor(c: ControleForm, bruto: unknown, atual: ValorForm): ValorForm {
  if (c.tipo === "caixa") return bruto === true || bruto === "true" || bruto === "1" || bruto === 1 || bruto === "on";
  if (c.tipo === "numero") {
    if (bruto === "" || bruto === null) return "";
    const s = String(bruto).trim().replace(",", ".");
    const n = Number(s);
    return Number.isFinite(n) && s !== "" ? dentro(n, c) : atual;
  }
  if (c.tipo === "radio" || c.tipo === "selecao") {
    const v = String(bruto ?? "");
    if (c.fonte === "categorias") return v.slice(0, 80);
    const ok = (c.opcoes ?? []).some((o) => o.v === v && !o.desab);
    return ok ? v : atual;
  }
  const max = c.tamanho ?? (c.tipo === "area" ? 500 : 200);
  return String(bruto ?? "").replace(/[<>]/g, "").trim().slice(0, max);
}

/** Junta o que veio do formulário com o que já estava gravado, só nos campos que existem. */
export function sanearForm(entrada: unknown, atual: ValoresForm = valoresPadrao()): ValoresForm {
  const o = (entrada ?? {}) as Record<string, unknown>;
  const r: ValoresForm = { ...valoresPadrao(), ...atual };
  for (const [k, v] of Object.entries(o)) {
    const c = porNome.get(k);
    if (c) r[k] = sanearValor(c, v, r[k] ?? "");
  }
  return r;
}
